// Parallel data fetching, matching app/page.tsx
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 0, visitors: 0 },
      notifications: [{ id: 1, message: 'No notifications' }],
      settings: { theme: 'system' },
    }
  }
}

function renderData(data: unknown) {
  if (Array.isArray(data)) {
    if (data.length === 0) return <p>None</p>
    return (
      <ul>
        {data.map((item, index) => (
          <li key={index}>
            {item !== null && typeof item === 'object'
              ? JSON.stringify(item)
              : String(item)}
          </li>
        ))}
      </ul>
    )
  }

  if (data !== null && typeof data === 'object') {
    return (
      <ul>
        {Object.entries(data).map(([key, value]) => (
          <li key={key}>
            {key}:{' '}
            {value !== null && typeof value === 'object'
              ? JSON.stringify(value)
              : String(value)}
          </li>
        ))}
      </ul>
    )
  }

  return <p>{String(data)}</p>
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>
      <section>
        <h3>Analytics</h3>
        {renderData(analytics)}
      </section>
      <section>
        <h3>Notifications</h3>
        {renderData(notifications)}
      </section>
      <section>
        <h3>Settings</h3>
        {renderData(settings)}
      </section>
    </div>
  )
}

